{
  "a_sentences": [
    {
      "a_text": "Selon l'art. 538 al. 2 CO, des prétentions en dommages-intérêts peuvent naître entre les associés d'une société simple lorsque l'un d'eux n'agit pas avec la diligence requise dans les affaires de la société (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le demandeur à l'action en responsabilité de l'art. 538 CO doit prouver le dommage subi (art. 42 al. 1 CO) (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Lorsque le dommage est difficile à prouver, l'art. 42 al. 2 CO s'applique (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Les faits pertinents doivent être allégués de manière suffisamment motivée pour que la partie adverse puisse se déterminer clairement et que le juge puisse dresser le tableau exact des faits admis ou contestés (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Il ne suffit pas que la pièce produite contienne les informations nécessaires sous une forme ou une autre (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Pour les postes du préjudice allégués de manière générale, il incombe à la partie demanderesse de détailler et d'apporter la preuve de son dommage en indiquant précisément à quoi ces préjudices correspondent et dans quelle ampleur (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le raisonnement de la juridiction cantonale n'est pas critiquable sur ce point (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral confirme que le dommage n'a pas été suffisamment allégué ni prouvé (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
